#include "viterbi_viterbi.h"

int viterbi(tok_t obs[N_OBS], prob_t init[N_STATES], prob_t transition[N_STATES * N_STATES], prob_t emission[N_STATES * N_TOKENS], state_t path[N_OBS]) {
    // We'll use two arrays for the forward pass (current and previous time step) and a backtrack table.
    state_t backtrack[N_OBS][N_STATES]; // backtrack[t][j] = best previous state for state j at time t (for t>=1)
    prob_t llike_prev[N_STATES];        // likelihood for the previous time step
    prob_t llike_curr[N_STATES];        // likelihood for the current time step

    // Step 1: Initialization for the first observation (t=0)
    for (int i = 0; i < N_STATES; i++) {
        llike_prev[i] = init[i] + emission[i * N_TOKENS + obs[0]];
        // Note: backtrack[0][i] is not used, so we don't initialize it.
    }

    // Step 2: Iterate over the remaining observations (t from 1 to N_OBS-1)
    for (int t = 1; t < N_OBS; t++) {
        for (int j = 0; j < N_STATES; j++) {
            // Start by assuming the best previous state is 0
            prob_t min_val = llike_prev[0] + transition[0 * N_STATES + j];
            state_t min_state = 0;
            // Check all other previous states
            for (int i = 1; i < N_STATES; i++) {
                prob_t val = llike_prev[i] + transition[i * N_STATES + j];
                if (val < min_val) {
                    min_val = val;
                    min_state = i;
                }
            }
            // Compute the current likelihood for state j at time t
            llike_curr[j] = min_val + emission[j * N_TOKENS + obs[t]];
            // Record the best previous state for backtracking
            backtrack[t][j] = min_state;
        }
        // Copy current to previous for the next iteration
        for (int i = 0; i < N_STATES; i++) {
            llike_prev[i] = llike_curr[i];
        }
    }

    // Step 3: Find the end state (at the last time step, t = N_OBS-1)
    state_t end_state = 0;
    prob_t min_val = llike_prev[0];
    for (int i = 1; i < N_STATES; i++) {
        if (llike_prev[i] < min_val) {
            min_val = llike_prev[i];
            end_state = i;
        }
    }

    // Step 4: Backtrack to find the most likely state sequence
    path[N_OBS-1] = end_state;
    for (int t = N_OBS-2; t >= 0; t--) {
        end_state = backtrack[t+1][end_state];
        path[t] = end_state;
    }

    return 0;
}
